    title: "需求与供给：市场如何形成价格",
    subtitle: "区分曲线上的移动与整条曲线移动，建立市场分析的基本语法。",
    tags: ["需求", "供给", "需求量", "供给量"],
    objectives: ["说明需求定律和供给定律", "区分需求变化与需求量变化", "识别收入、成本、预期等非价格因素"],
