      steps: ["8 月 3 日由采购订单、收货单和发票支持：借库存 30,000，贷应付 30,000。", "过账后，库存与应付总账分别增加 30,000。", "8 月 20 日银行付款：借应付 18,000，贷银行存款 18,000；应付明细尚余 12,000。"],
