          "限价 80 元（第 15 课的价格上限）：供给 0.1Q = 80 得量 800，需求 200 − 0.1Q = 80 得要 1,200，短缺 400 台；成交卡在 800，被卡掉的 200 台里买家愿付（120 元滑向 100）与卖家成本（80 元爬向 100）平均差 40 元，DWL = ½ × 200 × 40 = 4,000——同是「让价格变低」，限价掐量不轻、还不给任何回补。垄断（第 40 课）是第四个卡口：厂商自己把量压到 MR = MC，DWL ½ × (700−400) × (60−30)＝4,500 元的那块三角，与限价共享「量不足」的同一算法。",
