          "三条偏好公理撑起整栋楼：完备性（任何两个组合都能比）、传递性（A 好于 B、B 好于 C，则 A 好于 C）、多多益善（数量更多的组合至少不差）。它们弱到几乎无法反驳，却能推出曲线的全部形状——这是微观经济学「少假设、多结论」的招牌手法，也是第 45 课信息不对称之后，我们再次给「看不见的心」建模型。",
