          "凸性的生意读法：MRS 递减意味着客户对「已经囤足的品类」越来越不肯加价——这正解释了第 29 课的交叉弹性为什么随持有量变化，也预告了第 59 课切点的存在：预算线是直的，曲线越躺越平，两者最多切一次。",
