          "额度真正的价值在触发时点之前：第 41 课写死了缺口出现前 60 天启动动作，而授信审批通常要 30—60 天。等缺口显形再去谈额度，价格与条件都由对方定；这是短期融资里最贵的一个错误，也是唯一没有账面记录的错误。"
