          "这个优先序要和第 63 课的收款阶梯拼成一张表：同一周里，一边催收客户的钱、一边挑最便宜的方式补自己的钱，两侧都用 6% 做基准。营运资金管理的完整动作，就是把 36.7%、24.5%、7.3%、6%、0.3% 这几个数字按大小排好，然后每次都按序行动。",
