          "所以真正的选择不是「哪种更真实」，而是「哪种与你的定价、考核和报税口径最一致」。选定之后要稳定使用；年年换方法，等于把同一堆交易换一套语言讲，跨期比较立刻失真——这正是第 23 课九字诀里「比」字要抓的东西。",
