          "两个数一起摆出来：销售成本相差 3,000 元、期末存货也相差 3,000 元——一边的利润就是另一边的资产，这是复式记账给的免费对账。物价上行期的方向是固定的：先进先出成本低、利润高、存货账面贴近现价；加权平均成本被抬高、利润低、但把价格波动摊平。移动加权平均则更细：每进一次货就重算单价，适合单价高、批次乱的设备配件。",
