          "另一条分界线是盘存制。永续制逐笔记收发存，任何时刻都有账面余额，差错与损耗会在盘点时露出差额；定期制平时不记发出，月末用「期初＋本期购进−实地盘点」倒挤销售成本，于是短少、毁损、记账错误全都被一起吞进成本，销售毛利率会静悄悄地下滑却找不到原因。小公司用定期制省事，代价是让第 27 课月结时那段最该看的差异检查彻底失效——省下的时数，会用看不见的方式收回去。",
